process.commandLine:
hp=${HTTPS_PROXY#http://}
p() { printf 'CONNECT %s HTTP/1.1\r\n\r\n' "$1" | nc -w 3 "${hp%:*}" "${hp##*:}" | head -n1 | cut -d' ' -f2; }
echo DENIED=$(p 1.1.1.1:443)
echo DENIED_ANY_PORT=$(p 1.0.0.1:80)
echo NAME_DENIED=$(p one.one.one.one:443)
echo PORT_DENIED=$(p 9.9.9.9:443)
echo PORT_OTHER=$(p 9.9.9.9:853)
echo EXCEPT_ALLOWED=$(p 8.8.8.8:443)
echo EXCEPT_SIBLING=$(p 8.8.8.4:443)
echo ANY_PROTOCOL_DENIED=$(p 8.8.4.4:853)
echo ANY_PROTOCOL_OTHER=$(p 8.8.4.4:443)
echo NAME_ALLOWED=$(p dns.google:443)
nslookup dns.google >/tmp/ns 2>&1 && grep -q '8\.8\.[48]\.[48]' /tmp/ns && echo DNS=RESOLVED || echo DNS=FAILED
timeout 8 nslookup one.one.one.one 1.1.1.1 >/dev/null 2>&1 && echo UDP_DIRECT=REACHED || echo UDP_DIRECT=BLOCKED
ping -c 1 -W 3 1.1.1.1 >/dev/null 2>&1 && echo ICMP=REACHED || echo ICMP=BLOCKED
nc -z -w 3 8.8.8.8 443 && echo DIRECT=REACHED || echo DIRECT=BLOCKED
